import{Lt as e,Z as t,_t as n,vt as r}from"./chunks/framework.CsLlEPF4.js";var i=JSON.parse(`{"title":"贡献指南：如何新增样式","description":"","frontmatter":{"sidebar":false,"comments":false,"editLink":false,"styleData":null},"headers":[],"relativePath":"styles/detail/CONTRIBUTING.md","filePath":"styles/detail/CONTRIBUTING.md"}`),a={name:`styles/detail/CONTRIBUTING.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="贡献指南-如何新增样式" tabindex="-1">贡献指南：如何新增样式 <a class="header-anchor" href="#贡献指南-如何新增样式" aria-label="Permalink to “贡献指南：如何新增样式”">​</a></h1><p>本文档说明如何在本仓库中新增一个 CSL 样式。</p><h2 id="_1-样式名称" tabindex="-1">1. 样式名称 <a class="header-anchor" href="#_1-样式名称" aria-label="Permalink to “1. 样式名称”">​</a></h2><p>新增样式前，请先确定样式的名称。建议遵循以下规则：</p><ul><li>应包含期刊/学校/标准/体例的名称。</li><li>学校的院系使用“学校 - 院系”格式。</li><li>本科生的学位论文样式标注“（本科）”，研究生不标注。</li><li>如果有特定引用格式，在括号中标注“顺序编码”、“著者-出版年”、或“脚注”。</li></ul><p>可以参考仓库中的样式名称。</p><h2 id="_2-在-src-下创建样式目录" tabindex="-1">2. 在 <code>src</code> 下创建样式目录 <a class="header-anchor" href="#_2-在-src-下创建样式目录" aria-label="Permalink to “2. 在 src 下创建样式目录”">​</a></h2><p>每个样式都必须在 <code>src</code> 下使用独立目录。 建议结构：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/</span></span>
<span class="line"><span>	your-style-name/</span></span>
<span class="line"><span>		your-style-name.csl</span></span>
<span class="line"><span>		items.json   # 可选</span></span>
<span class="line"><span>		cites.json   # 可选</span></span></code></pre></div><h2 id="_3-info-填写规则" tabindex="-1">3. <code>&lt;info&gt;</code> 填写规则 <a class="header-anchor" href="#_3-info-填写规则" aria-label="Permalink to “3. &lt;info&gt; 填写规则”">​</a></h2><p>请确保样式的 <code>&lt;info&gt;</code> 信息完整、规范，至少满足以下要求：</p><ul><li><code>title</code>：与样式名称一致。</li><li><code>id</code>：使用样式页面地址（例如 <code>https://zotero-chinese.com/styles/your-style-name</code>），且应唯一。</li><li><code>link rel=&quot;self&quot;</code>：指向本样式地址，与 <code>id</code> 一致。</li><li><code>link rel=&quot;template&quot;</code>：如果是基于某个样式派生，建议保留并指向上游模板样式。</li><li><code>link rel=&quot;documentation&quot;</code>：期刊/学校的官网格式规范的链接。如果有单独的文件，使用两个 <code>link</code> 分别给出网页和文件的链接。</li><li><code>issn</code>：期刊可以列出 ISSN 号。</li><li><code>summary</code>：注明格式规范的文件名称、发布日期、文件号（可选）， 例如“《经济研究》参考文献索引及用录体例说明（2025-01-03）”、 “北京理工大学研究生学位论文撰写规范（研函〔2026〕024号），2026年3月31日发布”。 也可以补充说明相对于基准格式的修改细节。</li><li><code>updated</code>：更新时间应为有效时间格式。</li></ul><p>注意事项：</p><ul><li>不要手动修改自动生成文件（如 <code>metadata.json</code>、<code>index.md</code>），脚本会覆盖这些文件。</li></ul>`,14)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};